update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p026","body":"گہری گہری سانسیں ، بےخدی کے جام لیے\nدن خوشی کے گزر گئے ، غم کی شام لیے\n\nآج شب جانے کیوں دل اسے پکار چلا\nاک عمر ہوئی  تھی زبان کو جس کا نام لیے"},{"slug":"tum-p027","body":"شوقِ تمنا بھی ہے ساقی بھی ایاغ بھی\nجستجو اپنی منزل کی اور ٹھیک سراغ بھی\n\nرات کیا گئی کہ جلتی رہی شمع کی لَو\nدن کیا آیا کہ بجھاںے پڑے چراغ بھی"},{"slug":"tum-p028","body":"نہیں نگاہ میں ساحل تو کیوں کر پار جائیں\nنہیں جب وصال ممکن تو کیوں نہ ہار جائیں\n\nاحمد ؔ زندگی کے خرابوں میں الجھے ہیں اس قدر\nکہ ایک بار کی بازی تھی ہم بار بار جائیں"},{"slug":"tum-p029","body":"ہم اب عہد کرتے ہیں\nکہ تجھ کو بھول جائیں گے\nتجھے اب نہ ستائیں گے\nتجھے نہ یاد آئیں گے\nہم اب عہد کرتے ہیں\nکہ نہ دل جلائیں گے\nنہ خواب سجائیں گے\nنہ گیت گائیں گے\nنہ کچھ پڑھ کر سنائیں گے\nہم اب عہد کرتے ہیں\nکہ دل نے یاد کیا بھی تو\nنہ لوٹ کے آئیں گے\nنہ کوئی دیپ جلائیں گے\nلب سیئے جائیں گے\nہم اب عہد کرتے ہیں\nپر بھول کر بھی اچانک سے\nدل سنبھل نہ پائے تو\nتمہیں یاد بھی آئے تو\nتھوڑے بھول جائینگے۔۔۔۔۔۔!"},{"slug":"tum-p030","body":"دل لگانے کا حوصلہ نہیں رہا\nمیں جیسا تھا اب ویسا نہیں رہا\n\nدکھ اور بھی ملے ، ضربیں اور بھی لگیں\nپر تیرے فراق سا وہ مزا نہیں رہا\n\nجس سے رہیں امیدیں خوب برسنے کیں\nوہ ابر ایسا گرجا کہ بھیگا نہیں رہا\n\nاب اگر تم کبھی اچانک روبرو بھی آئے\nتو دل اک پل سہی مگر دھڑکا نہیں رہا\n\nحیرت کہ تمہیں ہے بہت گلہ مجھ سے\nکسی کا کیا ، اب تو احمد ؔ اپنا نہیں رہا"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
